# ---- verification helpers -------------------------------------------------

# check "label" fn [args...] — run a verifier; on failure, offer to continue
# or bail (re-run resumes here since values are remembered).
check() {
  local label="$1"; shift
  printf '  %s… verifying:%s %s\n' "$DIM" "$RESET" "$label"
  if "$@" >/dev/null 2>&1; then
    printf '  %s✓ verified:%s %s\n' "$GREEN" "$RESET" "$label"
    return 0
  fi
  warn "could not verify: $label"
  if confirm "Continue anyway?"; then
    return 0
  fi
  printf '\n  %sStopped. Re-run this wizard when ready — it resumes at this stage.%s\n\n' "$DIM" "$RESET"
  exit 1
}

v_do_token() {
  curl -sf -o /dev/null -H "Authorization: Bearer ${DIGITALOCEAN_ACCESS_TOKEN}" \
    https://api.digitalocean.com/v2/account
}
v_dns_points_to_rip() {
  local got; got="$(dig +short "$DOMAIN" A 2>/dev/null | tail -n1)"
  [[ "$got" == "$RESERVED_IP" ]]
}
v_port_open()  { nc -z -w5 "$RESERVED_IP" "$1"; }
v_tls_cert()   {
  echo | openssl s_client -servername "$DOMAIN" -connect "${DOMAIN}:443" 2>/dev/null \
    | openssl x509 -noout -checkend 0 >/dev/null 2>&1
}
v_https_up()   { curl -sf -o /dev/null --max-time 10 "https://${DOMAIN}/up"; }
v_main_has_adr066() {
  git -C "$REPO_DIR" fetch -q origin 2>/dev/null || return 1
  git -C "$REPO_DIR" log origin/main --oneline -n 50 | grep -q "$ADR066_MARKER"
}
v_old_droplet_gone() {
  local code
  code="$(curl -s -o /dev/null -w '%{http_code}' \
    -H "Authorization: Bearer ${DIGITALOCEAN_ACCESS_TOKEN}" \
    "https://api.digitalocean.com/v2/droplets/${OLD_DROPLET_ID}")"
  [[ "$code" == "404" ]]
}
v_forge_hook() {
  [[ -n "${FORGE_DEPLOY_HOOK:-}" ]] && curl -sf -o /dev/null -X POST "$FORGE_DEPLOY_HOOK"
}
v_registry_gone() {
  local code
  code="$(curl -s -o /dev/null -w '%{http_code}' \
    -H "Authorization: Bearer ${DIGITALOCEAN_ACCESS_TOKEN}" \
    "https://api.digitalocean.com/v2/registry")"
  [[ "$code" == "404" ]]
}
v_admin_url()    { curl -sf -o /dev/null --max-time 10 "https://admin.pekangame.space"; }
v_store_url()    { curl -sf -o /dev/null --max-time 10 "https://pekangame.space"; }
v_reseller_url() { curl -sf -o /dev/null --max-time 10 "https://reseller.pekangame.space"; }

