cat > "$NGINX_OUT" <<'EOF'
    # Reverb WebSocket (ADR-047 / ADR-066) — proxy /app/ to the Reverb daemon
    location /app/ {
        proxy_pass http://127.0.0.1:8080;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "Upgrade";
        proxy_read_timeout 60s;
    }
EOF
printf '  %s✓ wrote%s %s\n' "$GREEN" "$RESET" "$NGINX_OUT"
open_url "https://forge.laravel.com/servers"
step "${DOMAIN} site → 'Apps' or the site menu → 'Nginx Configuration' ('Edit Files')."
step "Paste the block from ${NGINX_OUT} INSIDE the 'server { ... }' block,"
step "just above the existing 'location / { ... }' line."
step "Click 'Save' — Forge tests the config and reloads nginx."
pause "Nginx block added and saved (no error)? Press Enter."

# ── 12 ───────────────────────────────────────────────────────────────────
stage "Forge — Horizon"
say "Horizon supervises the queue workers, reading config/horizon.php's four"
say "per-queue supervisors (orders / price-sync / backups / supplier-request-logs)."
open_url "https://forge.laravel.com/servers"
step "${DOMAIN} site → 'Queue' tab → enable 'Horizon' (Forge manages 'php artisan horizon')."
step "Confirm the environment shows APP_ENV=production (from stage 7) so it picks the"
step "'production' supervisor block."
pause "Horizon enabled? Press Enter."
note "It will only actually start once the first deploy has pulled the code + vendor/."

# ── 13 ───────────────────────────────────────────────────────────────────
stage "DigitalOcean — move the Reserved IP to the new droplet"
say "DNS for ${DOMAIN} already points at ${RESERVED_IP}. Moving the Reserved IP"
say "onto pekangame-prod makes the domain resolve there. No live traffic exists yet,"
say "so there's nothing to interrupt."
open_url "https://cloud.digitalocean.com/networking/reserved_ips"
step "Find ${RESERVED_IP} (currently on ${OLD_DROPLET_NAME})."
step "Click the '...' menu → 'Reassign Reserved IP' → select 'pekangame-prod' → Reassign."
pause "Reassigned? Press Enter (DNS/routing can take 1-2 min)."
check "${DOMAIN} resolves to ${RESERVED_IP}" v_dns_points_to_rip
check "port 80 is reachable on ${RESERVED_IP} (new droplet + firewall tag)" v_port_open 80

# ── 14 ───────────────────────────────────────────────────────────────────
stage "Forge — SSL (Let's Encrypt)"
say "Now that the domain resolves to this server, issue the certificate."
open_url "https://forge.laravel.com/servers"
step "${DOMAIN} site → 'SSL' → 'Let's Encrypt' → domain ${DOMAIN} → 'Obtain Certificate'."
step "When it finishes, click 'Activate' if Forge doesn't auto-activate it."
pause "Certificate obtained + activated? Press Enter."
check "a valid, unexpired TLS certificate is served for ${DOMAIN}" v_tls_cert

# ── 15 ───────────────────────────────────────────────────────────────────
stage "GitHub — merge staging → main"
say "main is the deploy branch. It needs ADR-066 (Docker removed, Forge CI) before"
say "the first Forge deploy pulls it."
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  say "Opening a staging → main PR..."
  gh pr create --repo "$REPO" --base main --head staging \
    --title "release: staging → main (ADR-066 Forge cutover)" \
    --body "Promotes ADR-066 (Forge deploy, Docker artifacts removed) plus everything already verified on staging. Merge with a merge commit (--no-ff), per AGENTS.md." \
    2>/dev/null || note "(PR may already exist — that's fine.)"
  gh pr view --repo "$REPO" staging --web 2>/dev/null || open_url "https://github.com/${REPO}/compare/main...staging"
else
  open_url "https://github.com/${REPO}/compare/main...staging"
  step "Click 'Create pull request', base = main, compare = staging."
fi
step "Wait for CI to go green on the PR."
step "Merge it — use 'Create a merge commit' (NOT squash), per the repo's workflow."
pause "Merged to main? Press Enter."
check "origin/main now contains the ${ADR066_MARKER} commit" v_main_has_adr066

# ── 16 ───────────────────────────────────────────────────────────────────
stage "Forge — first deploy"
open_url "https://forge.laravel.com/servers"
step "${DOMAIN} site → 'Apps' → 'Deploy Now'."
step "Watch the deploy log. The first run is the slow one (full composer install)."
step "It ends by curl-ing https://${DOMAIN}/up — the deploy fails if that isn't 200."
pause "Deploy finished green? Press Enter."
check "GET https://${DOMAIN}/up returns 200" v_https_up

# ── 17 ───────────────────────────────────────────────────────────────────
stage "First-boot — seed the production database"
say "The schema is migrated (deploy script). Now seed the one-time production data"
say "and create the first super admin from ADMIN_EMAIL / ADMIN_PASSWORD."
open_url "https://forge.laravel.com/servers"
step "${DOMAIN} site → open the web SSH terminal (or 'Commands' → run a command)."
step "Run, one line:"
say  "   cd ${FORGE_APP_PATH} && php artisan db:seed --class=ProductionSeeder --force"
step "Expect: primary reseller + branding + payment methods + crawler rules + hero slide,"
step "and 'Created super admin: <your email>'."
pause "Seed completed without error? Press Enter."
say "Now confirm you can log in:"
open_url "https://${DOMAIN}/up"
step "(Admin UI itself is on Vercel — stages 22-23. For now just confirm the API is healthy.)"
pause "Press Enter."

# ── 18 ───────────────────────────────────────────────────────────────────
stage "DigitalOcean — destroy the old droplet"
warn "IRREVERSIBLE. Only proceed once ${DOMAIN}/up is green on the NEW server (stage 16)."
say "Old droplet: ${OLD_DROPLET_NAME}  (id ${OLD_DROPLET_ID}) — the empty box that"
say "was created without an SSH key. Nothing runs on it."
check "the new server is serving /up over HTTPS right now" v_https_up
open_url "https://cloud.digitalocean.com/droplets"
step "Open '${OLD_DROPLET_NAME}' → 'Destroy' → 'Destroy this Droplet'."
step "Type the droplet name to confirm when DO asks."
if confirm "Have you destroyed ${OLD_DROPLET_NAME} in the DO panel?"; then
  check "DO API no longer knows droplet ${OLD_DROPLET_ID}" v_old_droplet_gone
else
  SKIPPED+=("Destroy old droplet ${OLD_DROPLET_NAME} (id ${OLD_DROPLET_ID})")
  warn "left for later — do it once you're confident in the new server."
fi

# ── 19 ───────────────────────────────────────────────────────────────────
stage "GitHub — FORGE_DEPLOY_HOOK secret + verify auto-deploy"
say "CI's 'deploy' job POSTs this URL after the 5 test jobs pass on main."
open_url "https://forge.laravel.com/servers"
step "${DOMAIN} site → 'Apps' → 'Deploy Trigger' (or 'Deployment') → copy the URL."
step "It looks like: https://forge.laravel.com/servers/NNNN/sites/MMMM/deploy/http?token=..."
ask_secret FORGE_DEPLOY_HOOK "Paste the Forge deploy webhook URL:"
write_env FORGE_DEPLOY_HOOK "$FORGE_DEPLOY_HOOK"
set_secret FORGE_DEPLOY_HOOK "$FORGE_DEPLOY_HOOK"
say "Test it fires a deploy:"
check "POST to the hook is accepted by Forge" v_forge_hook
step "Check the Forge deploy log shows a deployment that was just queued/started."
pause "Deploy triggered by the hook? Press Enter."

# ── 20 ───────────────────────────────────────────────────────────────────
stage "Cleanup — retire the Docker-path resources"
say "None of these are used any more (ADR-066)."
open_url "https://cloud.digitalocean.com/registry"
step "DO Container Registry → Settings → 'Delete Registry' (the 'pekangame' registry, \$5/mo)."
pause "Registry deleted? Press Enter."
check "DO API reports no container registry" v_registry_gone
say "Stale GitHub secrets (no longer referenced by ci.yml):"
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  for s in DIGITALOCEAN_ACCESS_TOKEN DEPLOY_HOST DEPLOY_USER DEPLOY_SSH_KEY; do
    if gh secret delete "$s" --repo "$REPO" >/dev/null 2>&1; then
      printf '  %s✓ deleted%s GitHub secret %s\n' "$GREEN" "$RESET" "$s"
    else
      note "  (secret $s not present — nothing to delete)"
    fi
  done
else
  open_url "https://github.com/${REPO}/settings/secrets/actions"
  step "Delete: DIGITALOCEAN_ACCESS_TOKEN, DEPLOY_HOST, DEPLOY_USER, DEPLOY_SSH_KEY"
  pause "Deleted? Press Enter."
fi

# ── 21 ───────────────────────────────────────────────────────────────────
stage "Monitoring — DO alerts + external uptime check"
say "ADR-020's addendum made these mandatory, not optional."
open_url "https://cloud.digitalocean.com/monitoring/alerts"
step "Create Alert Policy → CPU > 60% for 5 min → notify your email → apply to 'pekangame-prod'."
step "Create Alert Policy → Memory > 70% for 5 min → same."
step "Create Alert Policy → Disk > 80% → same."
pause "Three alert policies created? Press Enter."
open_url "https://dashboard.uptimerobot.com/monitors"
step "New monitor → HTTP(s) → URL: https://${DOMAIN}/up → interval 5 min → alert contact = you."
pause "Uptime monitor live? Press Enter."
note "Optional: also add https://forge.laravel.com health-check heartbeats on the Horizon"
note "and Reverb daemons (Forge → server → 'Monitoring')."

# ── 22 ───────────────────────────────────────────────────────────────────
stage "Vercel — import the three frontends"
say "storefront / admin / reseller each become a Vercel project on the JW Brothers team."
open_url "https://vercel.com/new"
say "For EACH of the three (repeat this stage's steps 3x):"
step "Import ${REPO} → team: JW Brothers."
step "storefront:  Root Directory = storefront   | Framework = Next.js"
step "admin:       Root Directory = admin"
step "reseller:    Root Directory = reseller"
step "Environment Variables (all three):"
say  "   NEXT_PUBLIC_API_URL=https://${DOMAIN}"
say  "   NEXT_PUBLIC_REVERB_APP_KEY=${REVERB_APP_KEY_VALUE}"
say  "   NEXT_PUBLIC_REVERB_HOST=${DOMAIN}"
say  "   NEXT_PUBLIC_REVERB_PORT=443"
say  "   NEXT_PUBLIC_REVERB_SCHEME=https"
step "admin + reseller ALSO need:  NEXT_PUBLIC_SITE_URL  and the PrimeReact licence key"
step "   (NEXT_PUBLIC_PRIMEUI_LICENSE_KEY — from your local admin/.env.local)."
step "storefront also:  NEXT_PUBLIC_SITE_URL=https://pekangame.space"
step "Deploy each. Note the *.vercel.app URL it gives you."
pause "All three projects deployed on *.vercel.app? Press Enter."

# ── 23 ───────────────────────────────────────────────────────────────────
stage "Vercel — custom domains + DNS"
say "Point the three hostnames at their Vercel projects. DNS is at Vercel already,"
say "so adding the domain in the project auto-creates the record."
open_url "https://vercel.com"
step "storefront project → Settings → Domains → add:  pekangame.space  (+ www redirect)."
step "admin project     → Settings → Domains → add:  admin.pekangame.space"
step "reseller project  → Settings → Domains → add:  reseller.pekangame.space"
step "Each shows 'Valid Configuration' once the record propagates (usually < 1 min at Vercel DNS)."
pause "All three domains valid? Press Enter."
check "https://pekangame.space responds"          v_store_url
check "https://admin.pekangame.space responds"    v_admin_url
check "https://reseller.pekangame.space responds" v_reseller_url

# ═════════════════════════════════════════════════════════════════════════

finish

printf '  %sNext, outside this wizard:%s\n' "$BOLD" "$RESET"
note "  - CHIP go-live: FPX approval → webhook config on the live domain → real test payment"
note "    → activate the 'fpx' payment_methods row."
note "  - Digiflazz: whitelist the egress IP (run 'curl -s ifconfig.me' in the Forge"
note "    web terminal) + ${RESERVED_IP} at Digiflazz; build the webhook controller."
note "  - Update docs/prd.md §14/§15 + the production memory: cutover DONE, go-live pending."
printf '\n'
warn "SHRED the local secret files now:"
note "  shred -u \"$ENV_FILE\" \"$HOME/pekangame-forge-DOTENV.txt\" 2>/dev/null || rm -f \"$ENV_FILE\" \"$HOME/pekangame-forge-DOTENV.txt\""
printf '\n'
